<?php if(!defined('ABSPATH'))exit;global $wpdb;$r=ICD_Visitas_Database::table('responsaveis');$e=ICD_Visitas_Database::table('escolas');$schools=$wpdb->get_results("SELECT id,nome FROM $e WHERE ativo=1 ORDER BY nome");$rows=$wpdb->get_results("SELECT r.*,e.nome escola FROM $r r JOIN $e e ON e.id=r.escola_id WHERE r.ativo=1 ORDER BY e.nome,r.principal DESC,r.nome");?>
<div class="wrap icd-admin"><h1>Responsáveis das escolas</h1><form class="icd-form-grid" method="post" action="<?php echo esc_url(ICD_Visitas_Helpers::action_url());?>"><?php wp_nonce_field('icd_save_responsavel');?><input type="hidden" name="action" value="icd_save_responsavel"><label>Escola<select required name="escola_id"><option value="">Selecione</option><?php foreach($schools as $x)echo '<option value="'.$x->id.'">'.esc_html($x->nome).'</option>';?></select></label><label>Nome<input required name="nome"></label><label>Cargo<input name="cargo" placeholder="Pedagoga, coordenação..."></label><label>Telefone<input name="telefone"></label><label>WhatsApp<input name="whatsapp"></label><label>E-mail<input type="email" name="email"></label><label class="icd-check"><input type="checkbox" name="principal"> Responsável principal</label><label class="full">Observações<textarea name="observacoes"></textarea></label><button class="button button-primary">Adicionar responsável</button></form><table class="widefat striped"><thead><tr><th>Escola</th><th>Nome</th><th>Cargo</th><th>Contato</th><th>Principal</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td><?php echo esc_html($x->escola);?></td><td><?php echo esc_html($x->nome);?></td><td><?php echo esc_html($x->cargo);?></td><td><?php echo esc_html($x->whatsapp?:$x->telefone);?></td><td><?php echo $x->principal?'Sim':'—';?></td></tr><?php endforeach;?></tbody></table></div>
